{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "실행 계획에서 확인한 병목을 실제 쿼리 개선 판단으로 연결할 수 있는지 확인한다. 신고 목록 조회에서 인덱스 추가와 조인 정리가 필요하다고 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 운영 화면의 신고 목록 조회 쿼리가 3.2초 걸렸다.",
          "task": "신고 목록 조회 쿼리에 인덱스를 추가하고 조인을 정리해 응답 시간을 0.4초로 줄였다.",
          "action": "실행 계획에서 확인한 전체 조인과 조회 조건을 근거로 병목 개선 지점을 고른 판단을 설명한다.",
          "result": "3.2초에서 0.4초로 줄어든 측정 결과가 해당 개선 판단을 뒷받침하는 이유를 설명한다."
        },
        "expectedEvidence": [
          "실행 계획에서 쿼리 병목 개선 지점을 고른 근거",
          "신고 테이블과 판매글 테이블의 전체 조인 및 조회 조건에 관한 관찰",
          "선택한 개선 지점을 뒷받침하는 개선 전후 응답 시간"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리를 3.2초에서 0.4초로 줄이셨을 때, 실행 계획에서 병목 개선 지점을 고른 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 전체 조인이나 조회 조건을 구체적으로 짚어 병목 개선 지점을 고른 근거를 설명한다.",
            "관찰한 병목과 인덱스 추가 또는 조인 정리가 필요한 이유를 연결해 해당 변경으로 조회 부담이 줄어드는 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실행 계획을 보고 인덱스나 조인을 개선 대상으로 골랐다고 답하지만 관찰한 내용은 포괄적이다.",
            "선택한 변경이 조회 속도를 높인다는 설명은 있으나 해당 쿼리의 병목과 연결되는 근거가 일부 빠져 있다."
          ]
        },
        "poor": {
          "criteria": [
            "실행 계획에서 무엇을 보고 개선 지점을 골랐는지 답하지 않고 변경 내용이나 최종 응답 시간만 반복한다.",
            "인덱스는 항상 빠르다는 식의 일반론을 말하거나 실행 계획의 관찰 내용과 관련 없는 근거를 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 추적한 장애 원인을 재발 방지 판단으로 연결할 수 있는지 확인한다. 스케줄러 중복 실행을 수정한 것과 별개로 배포 체크리스트에 스케줄러 항목을 넣은 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의를 받았다.",
          "task": "로그를 시간순으로 모아 두 서버에서 스케줄러가 동시에 실행되는 원인을 찾고 잠금을 두는 방식으로 수정했으며, 배포 체크리스트에 스케줄러 항목을 넣었다.",
          "action": "로그에서 확인한 중복 실행 원인이 배포 체크리스트에 스케줄러 항목을 추가하는 판단으로 이어진 근거를 설명한다.",
          "result": "잠금으로 오류를 수정한 뒤에도 체크리스트로 막으려 했던 반복 상황을 설명한다."
        },
        "expectedEvidence": [
          "재발 방지로 배포 체크리스트에 스케줄러 항목을 넣은 근거",
          "시간순 로그에서 확인한 두 서버의 스케줄러 동시 실행",
          "잠금 수정과 구별되는 체크리스트 추가의 예방 목적"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송을 로그로 추적하셨을 때, 재발 방지로 배포 체크리스트에 스케줄러 항목을 넣은 근거는 무엇이었나요?",
      "answerTip": "당시 생각을 차근차근 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "로그로 확인한 두 서버의 스케줄러 동시 실행을 체크리스트 항목 추가의 구체적인 근거로 연결한다.",
            "잠금으로 당장의 오류를 수정하는 것과 배포 시 같은 실행 문제가 반복되지 않게 점검하는 것의 차이를 근거에 담는다."
          ]
        },
        "acceptable": {
          "criteria": [
            "스케줄러 중복 실행을 다시 놓치지 않으려고 체크리스트에 추가했다고 답하지만 로그에서 확인한 사실과의 연결은 포괄적이다.",
            "체크리스트의 재발 방지 목적은 설명하지만 잠금 수정 이후에도 점검이 필요하다고 본 근거는 일부 빠져 있다."
          ]
        },
        "poor": {
          "criteria": [
            "체크리스트에 스케줄러 항목을 넣은 근거를 답하지 않고 로그 추적이나 잠금 수정 내용만 반복한다.",
            "체크리스트는 원래 필요하다는 일반론에 머물거나 확인한 장애 원인과 무관한 이유를 제시한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업 요청을 요구사항 문서로 구체화하면서 구현 범위를 합의할 수 있는지 확인한다. 세탁소 인터뷰에서 파악한 목적과 요청이 개발 담당 팀원과의 범위 조정 판단으로 이어진 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획은 플랜업스쿨 서비스 기획 과정의 팀 프로젝트였다.",
          "task": "기획 담당으로 세탁소 5곳 인터뷰를 통해 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "인터뷰에서 확인한 요청의 목적과 필요성을 범위 조정의 근거로 삼은 내용을 설명한다.",
          "result": "그 근거가 이번에 포함하거나 제외할 요구사항을 구분하는 판단에 어떤 차이를 만들었는지 설명한다."
        },
        "expectedEvidence": [
          "개발 담당 팀원과 요구사항 범위를 조정한 구체적인 근거",
          "그 근거를 뒷받침하는 세탁소 인터뷰의 요청이나 목적",
          "근거와 연결되는 요구사항의 포함·제외 판단"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳 인터뷰로 요구사항 정의서를 쓰셨을 때, 개발 담당 팀원과 범위를 조정한 근거는 무엇이었나요?",
      "answerTip": "핵심 답변을 먼저 말하고 설명을 덧붙이세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "범위를 조정한 근거를 인터뷰에서 확인한 요청의 목적이나 필요성과 구체적으로 연결한다.",
            "그 근거가 요구사항을 이번 범위에 포함하거나 제외하는 판단을 뒷받침하는지 명확하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "범위 조정의 근거를 제시하지만 인터뷰에서 확인한 요청과의 연결이 포괄적이다.",
            "포함하거나 제외할 요구사항을 판단한 방향은 드러나지만 해당 근거가 그 선택을 뒷받침하는 설명은 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항 정의서를 작성했다거나 팀원과 협의했다는 사실만 말하고 범위를 조정한 근거는 제시하지 못한다.",
            "인터뷰에서 확인한 목적이나 요청과 무관한 일반론만 제시해 요구사항 범위 판단을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능 흐름의 예외 상황을 화면설계에 구체적으로 반영할 수 있는지 확인한다. 예약·취소·알림 흐름에서 어떤 예외를 화면설계서에 담아야 한다고 판단했는지 그 선정 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 작성했다.",
          "task": "기획 담당으로 Figma를 사용해 화면설계서를 작성했다.",
          "action": "실제로 화면설계서에 담은 예외 상황을 짚고, 해당 상황을 선택한 근거를 화면의 상태나 흐름과 연결해 설명한다.",
          "result": "선정한 예외를 빠뜨리면 화면 동작이나 사용자 안내에서 무엇이 불분명해지는지 설명한다."
        },
        "expectedEvidence": [
          "화면설계서에 담을 예외 상황을 정한 구체적인 근거",
          "그 근거와 연결되는 실제 예약·취소·알림 흐름의 조건이나 화면 상태",
          "선정한 예외가 화면 동작이나 안내에 미치는 영향"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름을 화면설계서로 작성하셨을 때, 화면에 담을 예외 상황을 정한 근거는 무엇이었나요?",
      "answerTip": "한 가지 사례를 중심으로 짧게 설명해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제로 담은 예외 상황의 선정 근거를 해당 흐름의 조건이나 화면 상태 변화와 구체적으로 연결한다.",
            "그 예외를 화면설계서에 명시해야 하는 이유를 화면 동작이나 사용자 안내의 불분명함과 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황을 정한 근거를 제시하지만 실제 설계한 흐름의 조건이나 화면 상태와의 연결은 포괄적이다.",
            "화면 동작이나 안내에 필요하다는 설명은 있으나 해당 예외를 담아야 하는 이유의 구체성이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "화면설계서의 장수나 사용 도구만 설명하고 예외 상황을 정한 근거는 제시하지 못한다.",
            "예외 상황을 나열하거나 중요하다는 일반론만 말해 실제 기능 흐름에서 선택한 이유를 설명하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방이 의심스러울 때 투약을 멈추고 담당자에게 확인할 수 있는지 평가한다. 평소와 다른 용량을 단순히 따르지 않고 투약 전 확인이 필요하다고 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 근무 2년 차에 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어왔다.",
          "task": "지원자는 수술 전후 환자의 투약·처치를 맡았으며, 해당 처방의 투약을 멈추고 담당의에게 확인했다.",
          "action": "처방 용량에서 무엇을 의심했고 왜 확인 전 투약하면 안 된다고 판단했는지 설명한다.",
          "result": "담당의 확인 결과 입력 오류였다는 사실이 투약을 멈춘 판단을 어떻게 뒷받침했는지 설명한다."
        },
        "expectedEvidence": [
          "투약을 멈추고 담당의에게 확인한 판단 근거",
          "처방 용량이 평소 용량의 두 배였다는 구체적인 차이",
          "담당의 확인으로 밝혀진 입력 오류"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배로 들어왔을 때, 투약을 멈추고 담당의에게 확인하기로 판단한 근거는 무엇이었나요?",
      "answerTip": "본인이 겪은 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소 용량과 처방 용량의 차이를 짚어 투약 전 확인이 필요했던 이유를 구체적으로 설명한다.",
            "용량 차이만으로 처방 오류를 단정하지 않고 담당의 확인 전에는 투약을 진행하지 않아야 한다는 판단을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량이 평소와 달라 투약을 멈추고 확인했다고 답하지만 판단 근거가 포괄적이다.",
            "불확실한 처방을 그대로 수행하지 않아야 한다는 취지는 드러나지만 해당 처방과 연결한 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "투약 중단과 담당의 확인을 선택한 근거 대신 평소 투약 업무나 일반적인 주의사항만 말한다.",
            "의심스러운 처방도 그대로 투약하거나 담당의 확인 없이 임의로 용량을 바꿔도 된다는 판단을 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
